/** Browser-only image import. ZIPs are read from the central directory so entries
 * using data descriptors work as well as ZIPs generated by this app. */
export type ImportedPreviewAsset = {
  name: string
  originalName: string
  kind: 'character' | 'scene' | 'prop' | 'creature'
  image: string
  sourcePath: string
}
export type PreviewAssetImportResult = {
  assets: ImportedPreviewAsset[]
  skipped: string[]
  errors: string[]
}

const imageTypes: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
  gif: 'image/gif',
  avif: 'image/avif',
}
const maxImageSize = 15 * 1024 * 1024
const maxArchiveImagesSize = 1024 * 1024 * 1024
const maxArchiveEntries = 10000
const maxDirectorySize = 32 * 1024 * 1024
const maxCompressedImageSize = 20 * 1024 * 1024
const utf8 = new TextDecoder('utf-8', { fatal: true })

function readName(bytes: Uint8Array, utf8Flag: boolean) {
  try {
    return utf8.decode(bytes)
  } catch {
    if (utf8Flag) throw new Error('ZIP 文件名不是有效 UTF-8')
    // Common Windows Chinese ZIPs omit the UTF-8 flag and use GBK/GB18030.
    return new TextDecoder('gb18030').decode(bytes)
  }
}
function cleanPath(path: string) {
  return path.replace(/\\/g, '/')
}
function safePath(path: string) {
  const parts = cleanPath(path).split('/')
  return (
    !path.startsWith('/') &&
    !/^[a-z]:/i.test(path) &&
    parts.every((part) => part !== '..')
  )
}
function hiddenPath(path: string) {
  return cleanPath(path)
    .split('/')
    .some((part) => part === '__MACOSX' || part.startsWith('.'))
}
function fileType(path: string) {
  return imageTypes[path.split('.').pop()?.toLowerCase() || '']
}
function assetName(path: string) {
  return cleanPath(path)
    .split('/')
    .pop()!
    .replace(/\.[^.]+$/, '')
}
function assetKind(path: string): ImportedPreviewAsset['kind'] {
  const parts = cleanPath(path).split('/').slice(0, -1)
  for (const part of parts.reverse()) {
    const key = part.toLowerCase()
    if (
      [
        '背景',
        '场景',
        '环境',
        'scene',
        'scenes',
        'background',
        'backgrounds',
      ].includes(key)
    )
      return 'scene'
    if (['道具', '物品', 'prop', 'props'].includes(key)) return 'prop'
    if (['角色', '人物', 'character', 'characters'].includes(key))
      return 'character'
    if (['生物', '怪物', 'creature', 'creatures'].includes(key))
      return 'creature'
  }
  return 'character'
}
function toAsset(path: string, blob: Blob): ImportedPreviewAsset {
  const originalName = assetName(path)
  const name = originalName.replace(/@/g, '＠')
  return {
    name,
    originalName,
    kind: assetKind(path),
    image: URL.createObjectURL(blob),
    sourcePath: cleanPath(path),
  }
}
const crcTable = Array.from({ length: 256 }, (_, value) => {
  for (let i = 0; i < 8; i++)
    value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1
  return value >>> 0
})
function crc32(bytes: Uint8Array) {
  let crc = 0xffffffff
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 255]! ^ (crc >>> 8)
  return (crc ^ 0xffffffff) >>> 0
}
function u16(view: DataView, offset: number) {
  return view.getUint16(offset, true)
}
function u32(view: DataView, offset: number) {
  return view.getUint32(offset, true)
}
function requireRange(length: number, start: number, count: number) {
  if (start < 0 || count < 0 || start + count > length)
    throw new Error('ZIP 结构损坏或不完整')
}
async function inflateRaw(
  bytes: Uint8Array,
  limit: number,
): Promise<Uint8Array> {
  if (typeof DecompressionStream === 'undefined')
    throw new Error('浏览器不支持解压 ZIP，请解压后导入文件夹')
  let stream: DecompressionStream
  try {
    stream = new DecompressionStream('deflate-raw')
  } catch {
    throw new Error('浏览器不支持解压此 ZIP，请解压后导入文件夹')
  }
  const reader = new Blob([new Uint8Array(bytes).buffer])
    .stream()
    .pipeThrough(stream)
    .getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  try {
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      size += value.length
      if (size > limit) {
        await reader.cancel()
        throw new Error('图片解压后超过大小限制')
      }
      chunks.push(value)
    }
  } finally {
    reader.releaseLock()
  }
  const result = new Uint8Array(size)
  let offset = 0
  for (const chunk of chunks) {
    result.set(chunk, offset)
    offset += chunk.length
  }
  return result
}
async function importZip(
  file: File,
  result: PreviewAssetImportResult,
  textFiles?: File[],
) {
  // Read only the ZIP tail and central directory, then one image at a time.
  const tailStart = Math.max(0, file.size - 65557)
  const tail = new DataView(await file.slice(tailStart).arrayBuffer())
  let end = -1
  for (let pos = tail.byteLength - 22; pos >= 0; pos--) {
    if (
      u32(tail, pos) === 0x06054b50 &&
      pos + 22 + u16(tail, pos + 20) === tail.byteLength
    ) {
      end = pos
      break
    }
  }
  if (end < 0) throw new Error('ZIP 目录不存在或文件损坏')
  if (
    u16(tail, end + 4) ||
    u16(tail, end + 6) ||
    u16(tail, end + 8) !== u16(tail, end + 10)
  )
    throw new Error('不支持分卷 ZIP')
  const count = u16(tail, end + 10),
    directorySize = u32(tail, end + 12),
    directoryStart = u32(tail, end + 16)
  if (
    count === 0xffff ||
    directorySize === 0xffffffff ||
    directoryStart === 0xffffffff
  )
    throw new Error('不支持 ZIP64，请先解压后导入')
  if (count > maxArchiveEntries)
    throw new Error('ZIP 文件数量超过限制，请先解压后分批导入')
  if (directorySize > maxDirectorySize)
    throw new Error('ZIP 目录过大，请先解压后分批导入')
  requireRange(file.size, directoryStart, directorySize)
  if (directoryStart + directorySize > tailStart + end)
    throw new Error('ZIP 目录损坏')
  const directory = await file
    .slice(directoryStart, directoryStart + directorySize)
    .arrayBuffer()
  const view = new DataView(directory),
    bytes = new Uint8Array(directory)
  let cursor = 0,
    totalSize = 0
  for (let entry = 0; entry < count; entry++) {
    requireRange(bytes.length, cursor, 46)
    if (u32(view, cursor) !== 0x02014b50) throw new Error('ZIP 目录损坏')
    const flags = u16(view, cursor + 8),
      method = u16(view, cursor + 10),
      expectedCrc = u32(view, cursor + 16)
    const compressed = u32(view, cursor + 20),
      uncompressed = u32(view, cursor + 24),
      nameLength = u16(view, cursor + 28),
      extraLength = u16(view, cursor + 30),
      commentLength = u16(view, cursor + 32),
      local = u32(view, cursor + 42)
    const recordSize = 46 + nameLength + extraLength + commentLength
    requireRange(bytes.length, cursor, recordSize)
    const rawName = bytes.subarray(cursor + 46, cursor + 46 + nameLength)
    let path = ''
    try {
      path = cleanPath(readName(rawName, Boolean(flags & 0x800)))
    } catch {
      result.errors.push(`${file.name}：无法解码条目名称`)
      cursor += recordSize
      continue
    }
    cursor += recordSize
    if (!path || path.endsWith('/')) continue
    if (!safePath(path)) {
      result.errors.push(`${file.name}/${path}：路径无效`)
      continue
    }
    if (hiddenPath(path)) {
      result.skipped.push(`${file.name}/${path}`)
      continue
    }
    const mime = textFiles
      ? /\.(?:txt|md|markdown)$/iu.test(path)
        ? 'text/plain'
        : undefined
      : fileType(path)
    if (!mime) {
      result.skipped.push(`${file.name}/${path}`)
      continue
    }
    try {
      if (flags & 1) throw new Error('不支持加密 ZIP 条目')
      if (method !== 0 && method !== 8) throw new Error('不支持此压缩方式')
      if (
        compressed === 0xffffffff ||
        uncompressed === 0xffffffff ||
        local === 0xffffffff
      )
        throw new Error('不支持 ZIP64 条目')
      if (uncompressed > maxImageSize) throw new Error('图片超过 15 MB')
      if (compressed > maxCompressedImageSize) throw new Error('压缩条目过大')
      totalSize += uncompressed
      if (totalSize > maxArchiveImagesSize)
        throw new Error('ZIP 图片总大小超过 1 GiB')
      requireRange(file.size, local, 30)
      const localView = new DataView(
        await file.slice(local, local + 30).arrayBuffer(),
      )
      if (u32(localView, 0) !== 0x04034b50) throw new Error('ZIP 文件头损坏')
      const start = local + 30 + u16(localView, 26) + u16(localView, 28)
      requireRange(file.size, start, compressed)
      if (start + compressed > directoryStart)
        throw new Error('ZIP 条目范围无效')
      const input = new Uint8Array(
        await file.slice(start, start + compressed).arrayBuffer(),
      )
      const content =
        method === 0
          ? input
          : await inflateRaw(input, Math.min(maxImageSize, uncompressed))
      if (content.length !== uncompressed || crc32(content) !== expectedCrc)
        throw new Error('图片数据校验失败')
      const blob = new Blob([new Uint8Array(content).buffer], { type: mime })
      if (textFiles) {
        const scriptFile = new File([blob], path.split('/').pop()!, { type: mime })
        Object.defineProperty(scriptFile, 'webkitRelativePath', { value: path })
        textFiles.push(scriptFile)
      } else result.assets.push(toAsset(path, blob))
    } catch (error) {
      result.errors.push(
        `${file.name}/${path}：${error instanceof Error ? error.message : '读取失败'}`,
      )
    }
  }
}

/** Preserves the full base filename. Collisions gain their parent path then a number. */
export function resolvePreviewAssetNames(
  rows: ImportedPreviewAsset[],
  existingNames: string[] = [],
): ImportedPreviewAsset[] {
  const used = new Set(existingNames)
  return rows.map((row) => {
    let name = row.name
    if (used.has(name)) {
      const parent = cleanPath(row.sourcePath)
        .split('/')
        .slice(0, -1)
        .filter(Boolean)
        .join('/')
        .replace(/@/g, '＠')
      if (parent) name = `${parent}/${row.name}`
      const base = name
      let index = 2
      while (used.has(name)) name = `${base}-${index++}`
    }
    used.add(name)
    return { ...row, name }
  })
}

export async function importPreviewAssets(
  files: File[],
): Promise<PreviewAssetImportResult> {
  const result: PreviewAssetImportResult = {
    assets: [],
    skipped: [],
    errors: [],
  }
  for (const file of files) {
    const path = cleanPath(file.webkitRelativePath || file.name)
    if (!safePath(path)) {
      result.errors.push(`${path}：路径无效`)
      continue
    }
    if (hiddenPath(path)) {
      result.skipped.push(path)
      continue
    }
    if (/\.zip$/i.test(path)) {
      try {
        await importZip(file, result)
      } catch (error) {
        result.errors.push(
          `${path}：${error instanceof Error ? error.message : 'ZIP 读取失败'}`,
        )
      }
      continue
    }
    const mime = fileType(path)
    if (!mime) {
      result.skipped.push(path)
      continue
    }
    if (file.size > maxImageSize) {
      result.errors.push(`${path}：图片超过 15 MB`)
      continue
    }
    try {
      result.assets.push(toAsset(path, file.slice(0, file.size, mime)))
    } catch {
      result.errors.push(`${path}：图片读取失败`)
    }
  }
  return result
}

/** Retain script archive paths for the batch episode-grouping step. */
export async function readScriptVideoZip(file: File) {
  const result: PreviewAssetImportResult = {
    assets: [],
    skipped: [],
    errors: [],
  }
  const files: File[] = []
  await importZip(file, result, files)
  return { files, skipped: result.skipped, errors: result.errors }
}
